    public function getDescription(): string
    {
        return 'Ten more palettes, appended: monochrome, psychedelic, high contrast and seven others';
    }

    public function up(Schema $schema): void
    {
        foreach (self::PALETTES as $name => $document) {
            $this->addSql(
                <<<'SQL'
                    INSERT INTO palettes (name, position, document)
                    VALUES (:name, (SELECT coalesce(max(position), 0) + 1 FROM palettes), CAST(:document AS jsonb))
                    ON CONFLICT (name) DO NOTHING
                    SQL,
                ['name' => $name, 'document' => $document],
            );
        }
    }

    public function down(Schema $schema): void
    {
        // Only those nobody wears: a palette in use is held by tenant_palettes,
        // and taking it away would fail rather than strip anybody's screens.
        $this->addSql(
            'DELETE FROM palettes WHERE name IN (:names) AND name NOT IN (SELECT palette FROM tenant_palettes)',
            ['names' => array_keys(self::PALETTES)],
            ['names' => \Doctrine\DBAL\ArrayParameterType::STRING],
        );
    }
}
